<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='save'){$title=trim((string)($_POST['title']??''));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['active'])?1:0;$path=trim((string)($_POST['existing_image']??''));if(!empty($_FILES['image']['name']))$path=upload_image($_FILES['image'],'gallery','project');if($id){$st=$pdo->prepare('UPDATE gallery SET title=?,image_path=?,sort_order=?,active=? WHERE id=?');$st->execute([$title,$path,$sort,$active,$id]);}else{$st=$pdo->prepare('INSERT INTO gallery(title,image_path,sort_order,active) VALUES(?,?,?,?)');$st->execute([$title,$path,$sort,$active]);}flash('success','Gallery item saved.');}
 if($action==='delete'&&$id){$pdo->prepare('DELETE FROM gallery WHERE id=?')->execute([$id]);flash('success','Gallery item deleted.');}header('Location: gallery.php');exit;}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM gallery WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM gallery ORDER BY sort_order,id')->fetchAll();$pageTitle='Gallery';$active='gallery';require __DIR__.'/_header.php';?>
<p class="eyebrow">GALLERY</p><h1>Manage project photos</h1><section class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><input type="hidden" name="existing_image" value="<?=h($edit['image_path']??'')?>"><div class="two-col"><label>Title<input name="title" required value="<?=h($edit['title']??'')?>"></label><label>Order<input type="number" name="sort_order" value="<?=h((string)($edit['sort_order']??0))?>"></label></div><label>Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp" <?=$edit?'':'required'?>></label><label class="check-row"><input type="checkbox" name="active" <?=!$edit||!empty($edit['active'])?'checked':''?>> Active</label><button>Save item</button></form></section><div class="table-wrap"><table class="admin-table"><thead><tr><th>Image</th><th>Title</th><th>Order</th><th>Active</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php if($r['image_path']):?><img class="thumb" src="../<?=h($r['image_path'])?>" alt=""><?php endif;?></td><td><?=h($r['title'])?></td><td><?=$r['sort_order']?></td><td><?=$r['active']?'Yes':'No'?></td><td><div class="row-actions"><a class="button secondary" href="?edit=<?=$r['id']?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_footer.php';
